'use client';

import Link from 'next/link';
import { useState } from 'react';

const links = [
  ['Home', '/'],
  ['About Us', '/about'],
  ['Services', '/services'],
  ['Green Energy', '/green-energy'],
  ['Credentials', '/credentials'],
  ['Contact Us', '/contact']
];

export default function SiteHeader() {
  const [open, setOpen] = useState(false);

  function closeMenu() {
    setOpen(false);
  }

  return (
    <header>
      <nav id="navbar" aria-label="Primary navigation">
        <div className="nav-inner">
          <Link href="/" className="nav-logo" onClick={closeMenu}>
            <span className="nav-logo-icon">
              <img src="/images/maktub-logo.png" alt="Maktub Engineering logo" width="38" height="38" />
            </span>
            <span>
              <span className="nav-logo-text">Maktub Engineering</span>
              <span className="nav-logo-sub">&amp; General Supply Limited</span>
            </span>
          </Link>
          <div className="nav-links">
            {links.map(([label, href]) => <Link key={href} href={href} onClick={closeMenu}>{label}</Link>)}
          </div>
          <button
            className="hamburger"
            type="button"
            aria-label={open ? 'Close menu' : 'Open menu'}
            aria-expanded={open}
            aria-controls="mobileMenu"
            onClick={() => setOpen((value) => !value)}
          >
            <span aria-hidden="true">{open ? '×' : '☰'}</span>
          </button>
        </div>
      </nav>
      <div className={`mobile-menu${open ? ' open' : ''}`} id="mobileMenu" aria-label="Mobile navigation">
        {links.map(([label, href]) => <Link key={href} href={href} onClick={closeMenu}>{label}</Link>)}
      </div>
    </header>
  );
}
